const p=await read(d+'/protocol.json'),fetchInfo=await read(d+'/fetch-complete.json'),events=await read(d+'/events.json'),funding=await read(d+'/funding.json');assert.equal(hash(await fs.readFile(d+'/funding.json')),fetchInfo.fundingHash);const raw=new Map(),records=[],reconciliation=[],aggregates=[],tradeAggregates=[];let aggregationPriceFieldChecks=0;
for(const e of events){const file=encodeURIComponent(e.eventId)+'.json',bytes=await fs.readFile(d+'/raw/'+file);assert.equal(hash(bytes),fetchInfo.hashes[file]);const minute=JSON.parse(bytes).price;raw.set(e.eventId,minute);const original=await read('data/research/short-squeeze-volume-20261107/raw/'+encodeURIComponent(e.symbol)+'-data.json'),old=original.price.filter(b=>+b[0]>=e.entryAt&&+b[0]<e.entryAt+8*3600000);assert.equal(old.length,96);
for(let i=0;i<96;i++){const a=minute.slice(i*5,i*5+5),agg=[+a[0][1],Math.max(...a.map(b=>+b[2])),Math.min(...a.map(b=>+b[3])),+a.at(-1)[4]],prior=[1,2,3,4].map(j=>+old[i][j]);for(let j=0;j<4;j++)if(Math.abs(agg[j]-prior[j])>Math.max(1e-10,Math.abs(prior[j])*1e-8))aggregates.push({eventId:e.eventId,at:+old[i][0],field:['open','high','low','close'][j],minuteAggregated:agg[j],frozen5m:prior[j],firstMinuteNoTrades:+a[0][7]===0});const traded=a.filter(b=>+b[7]>0),real=traded.length?traded:a,realAgg=[+real[0][1],Math.max(...real.map(b=>+b[2])),Math.min(...real.map(b=>+b[3])),+real.at(-1)[4]];for(let j=0;j<4;j++){aggregationPriceFieldChecks++;if(Math.abs(realAgg[j]-prior[j])>Math.max(1e-10,Math.abs(prior[j])*1e-8))tradeAggregates.push({eventId:e.eventId,at:+old[i][0],field:j,minuteAggregated:realAgg[j],frozen5m:prior[j]});}}}
for(const sl of p.stopRoes)for(const be of p.beTriggerRoes){const id='SL'+sl+'_BE'+(be===null?'NONE':be),config={leverage:p.leverage,tpRoe:p.tpRoe,slRoe:sl,beTriggerRoe:be,costPct:p.costPct,stressCostPct:p.stressCostPct};
for(const e of events){const bars=raw.get(e.eventId),closed=diagnostics(replayClosedBE(bars,e,config,funding),bars),touch=replayTouchRange(bars,e,config,funding),worst=diagnostics(touch.worst,bars),best=diagnostics(touch.best,bars);
assert.ok(worst.netRoe<=best.netRoe+1e-8);assert.ok(closed.exitAt>=e.entryAt&&closed.exitAt<e.entryAt+8*3600000);if(closed.armedAt!==null)assert.ok(closed.armedAt<=closed.exitAt);
records.push({id,config,eventId:e.eventId,symbol:e.symbol,availableAt:e.availableAt,entryAt:e.entryAt,phase:e.phase,closed,touchWorst:worst,touchBest:best,touchUncertain:touch.uncertain,touchOutcomeCount:touch.outcomeCount,original5m:e.trade});
if(sl===20&&be===null)reconciliation.push({eventId:e.eventId,symbol:e.symbol,original5mRoe:e.trade.netRoe,new1mRoe:closed.netRoe,delta:closed.netRoe-e.trade.netRoe,originalKind:e.trade.kind,newKind:closed.kind,entryDifference:closed.entry-e.trade.entry,exitPriceDifference:closed.exit-e.trade.exit,exitTimeDifference:closed.exitAt-e.trade.exitAt});}}
const baseline=records.filter(r=>r.id==='SL20_BENONE'),baseMap=new Map(baseline.map(r=>[r.eventId,r])),groups={};
let seed=937251;const rand=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};
function ci(rs,key){const buckets=new Map();for(const r of rs){const k=key(r);if(!buckets.has(k))buckets.set(k,[]);buckets.get(k).push(r.closed.netRoe-baseMap.get(r.eventId).closed.netRoe);}const bs=[...buckets.values()],out=[];for(let n=0;n<2000;n++){let sum=0,count=0;for(let j=0;j<bs.length;j++){const b=bs[Math.floor(rand()*bs.length)];sum+=b.reduce((s,v)=>s+v,0);count+=b.length;}out.push(sum/count);}out.sort((a,b)=>a-b);return{clusters:bs.length,deltaMeanRoe95:[out[50],out[1949]]};}
for(const id of [...new Set(records.map(r=>r.id))]){const rs=records.filter(r=>r.id===id);groups[id]={config:rs[0].config,closed:statistics(rs),touchWorst:statistics(rs,'touchWorst'),touchBest:statistics(rs,'touchBest'),earlier:statistics(rs.filter(r=>r.phase!=='TEST')),later:statistics(rs.filter(r=>r.phase==='TEST')),uncertainTouchCases:rs.filter(r=>r.touchUncertain).length,baselineWinnersCut:rs.filter(r=>baseMap.get(r.eventId).closed.netRoe>0&&r.closed.netRoe<=0).length,improvedVsBaseline:rs.filter(r=>r.closed.netRoe>baseMap.get(r.eventId).closed.netRoe+1e-8).length,worsenedVsBaseline:rs.filter(r=>r.closed.netRoe<baseMap.get(r.eventId).closed.netRoe-1e-8).length,ciCoin:ci(rs,r=>r.symbol),ciTime:ci(rs,r=>Math.floor(r.availableAt/7200000))};}
const output={protocol:p,baselineSourceMean:events.reduce((s,e)=>s+e.trade.netRoe,0)/events.length,baseline1m:statistics(baseline),counts:{events:events.length,coins:new Set(events.map(e=>e.symbol)).size,configs:Object.keys(groups).length,replays:records.length,oneMinuteCandles:[...raw.values()].reduce((s,b)=>s+b.length,0)},reconciliation,aggregateDifferences:aggregates,tradeAggregateDifferences:tradeAggregates,aggregationPriceFieldChecks,groups,records};await save(d+'/results.json',output);await save(d+'/summary.json',{...output,records:undefined});console.log(JSON.stringify({counts:output.counts,aggregateDifferences:aggregates.length,tradeAggregateDifferences:tradeAggregates.length,aggregationPriceFieldChecks,baselineSourceMean:output.baselineSourceMean,baseline1m:output.baseline1m,reconciliationMismatches:reconciliation.filter(r=>Math.abs(r.delta)>1e-8),groups:Object.fromEntries(Object.entries(groups).map(([k,g])=>[k,{closed:g.closed,touchRange:[g.touchWorst.meanRoe,g.touchBest.meanRoe],ambiguous:g.uncertainTouchCases,winnersCut:g.baselineWinnersCut,earlier:g.earlier.meanRoe,later:g.later.meanRoe,deltaCI:g.ciCoin.deltaMeanRoe95}]))}));

